import{appendFileSync,existsSync,writeFileSync}from'node:fs'
import{basename,join}from'node:path'
const queued=new Map(),collected=new Map()
const record=value=>appendFileSync(process.env.QUEUED_TRACE,JSON.stringify({actor:'reporter',...value})+'\n')
const info=m=>({file:basename(m.moduleId),relativeModuleId:m.relativeModuleId,state:m.state(),children:m.children.size,childNames:[...m.children].map(c=>({type:c.type,name:c.name})),tests:[...m.children.allTests()].map(t=>({name:t.name,state:t.result().state})),errors:m.errors().map(e=>e.message),project:m.project.name,type:m.type,id:m.id})
export default class{
 onTestModuleQueued(m){queued.set(basename(m.moduleId),m);record({event:'queued',...info(m)})}
 onTestModuleCollected(m){const file=basename(m.moduleId);collected.set(file,m);record({event:'collected',sameQueued:m===queued.get(file),...info(m)})}
 onTestModuleEnd(m){const c=collected.get(basename(m.moduleId));record({event:'end',sameCollected:m===c,sameQueued:m===queued.get(basename(m.moduleId)),...info(m)})}
 onTestRunEnd(modules,errors,reason){record({event:'run-end',reason,errors:errors.map(e=>e.message),modules:modules.map(m=>({sameCollected:m===collected.get(basename(m.moduleId)),sameQueued:m===queued.get(basename(m.moduleId)),...info(m)}))})}
}

